import { randomUUID } from "node:crypto";
import { expect, type Request, test } from "@playwright/test";
import fixtures from "./fixtures/plotly-figures.json" with { type: "json" };
import { uploadFileToDashboard, waitForWorkspace } from "./helpers";

test.use({ launchOptions: { args: ["--enable-unsafe-swiftshader"] } });

// Figures generated by openbb-charting with Plotly.py 6.6.0 (Plotly.js 3.4.0).
test("renders backend financial, correlation, surface, and map figures", async ({ page }) => {
  test.setTimeout(120_000);
  const errors: string[] = [];
  page.on("pageerror", (error) => errors.push(error.message));
  let syncRequest: Request | undefined;
  page.on("request", (request) => {
    if (request.url().endsWith("/pro/dash/sync") && request.method() === "POST") {
      syncRequest = request;
    }
  });
  const { url } = await uploadFileToDashboard(page, "csv");
  const headers = {
    authorization: syncRequest!.headers().authorization,
    origin: new URL(url).origin,
  };
  const saved = await page.request.get(syncRequest!.url(), { headers });
  expect(saved.ok()).toBe(true);
  const tabId = new URL(url).pathname.split("/").at(-1)!;
  const dashboard = (await saved.json()).owned[tabId].content;
  const id = randomUUID();
  const innerTab = dashboard.data.currentTab ?? "";
  const endpoint = "http://plotly-backend.test/figure";
  dashboard.data.widgets.push({
    id,
    widgetId: "backend-chart",
    name: "Backend chart",
    type: "chart",
    innerTab,
    external: true,
    endpoint: { url: endpoint },
    gridData: { w: 30, h: 16 },
    storage: {},
  });
  dashboard.data.gridLayout[innerTab].push({ i: id, x: 0, y: 20, w: 30, h: 16 });
  const response = await page.request.post(syncRequest!.url(), {
    headers,
    data: { items: { [tabId]: dashboard } },
  });
  expect(response.ok()).toBe(true);

  const widget = page.locator(".group\\/widget").filter({
    has: page.getByText("Backend chart", { exact: true }),
  });
  for (const [name, figure] of Object.entries(fixtures.figures)) {
    await test.step(name, async () => {
      await page.unroute(`${endpoint}**`);
      await page.route(`${endpoint}**`, (route) => route.fulfill({
        json: { ...figure, layout: { template: fixtures.template, ...figure.layout } },
      }));
      await page.reload();
      await waitForWorkspace(page);
      const plot = widget.locator(".js-plotly-plot");
      await expect(plot).toBeVisible();
      await expect.poll(() => plot.evaluate((element) => {
        const graph = element as HTMLElement & { _fullData?: { type: string }[] };
        return graph._fullData?.map((trace) => trace.type);
      })).toEqual(figure.data.map((trace) => trace.type));

      if (name === "historical-prices") {
        await expect(plot.locator(".boxlayer .trace")).toBeVisible();
        await expect(plot.locator(".boxlayer .trace .box")).toHaveCount(12);
        await expect(plot.locator(".barlayer .trace")).toBeVisible();
      } else if (name === "correlation") {
        await expect(plot.locator(".heatmaplayer image")).toBeVisible();
      } else {
        await expect(plot.locator("canvas").first()).toBeVisible();
      }
    });
  }
  expect(errors).toEqual([]);
});
